  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

:root {
  --bg-page: #0f1117;
  --bg-card: #1a1d27;
  --bg-overlay: rgba(0, 0, 0, 0.75);
  --bg-modal: #1e2130;
  --border: #2e3248;
  --accent-red: #e53e3e;
  --accent-red-hover: #c53030;
  --accent-neutral: #3a3f55;
  --accent-neutral-hover: #4a4f6a;
  --text-primary: #e8eaf0;
  --text-secondary: #8b90a8;
  --text-muted: #5a5f78;
  --shadow: 0 20px 60px rgba(0, 0, 0, 0.6);
  --radius: 12px;
  --radius-sm: 8px;
}

body {
  background: var(--bg-page);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 2rem;
}

/* ── Image preview card ─────────────────────────────────────── */

.preview-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 320px;
  box-shadow: var(--shadow);
}

.preview-card__image-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  background: #12141f;
  overflow: hidden;
}

.preview-card__image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.preview-card__badge {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  color: var(--text-secondary);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,0.08);
}

.preview-card__body {
  padding: 1rem 1.125rem 1.25rem;
}

.preview-card__meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.875rem;
}

.preview-card__title {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.3;
}

.preview-card__size {
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
  margin-left: 0.5rem;
  padding-top: 2px;
}

.preview-card__actions {
  display: flex;
  gap: 0.5rem;
}

.btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.5rem 0.75rem;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.18s, border-color 0.18s, transform 0.1s;
  letter-spacing: 0.02em;
  line-height: 1;
}

.btn:active {
  transform: scale(0.97);
}

.btn--ghost {
  background: transparent;
  border-color: var(--border);
  color: var(--text-secondary);
}

.btn--ghost:hover {
  background: var(--accent-neutral);
  border-color: var(--accent-neutral-hover);
  color: var(--text-primary);
}

.btn--danger-outline {
  background: transparent;
  border-color: rgba(229, 62, 62, 0.45);
  color: #fc8181;
}

.btn--danger-outline:hover {
  background: rgba(229, 62, 62, 0.12);
  border-color: var(--accent-red);
  color: #feb2b2;
}

/* ── Modal overlay ──────────────────────────────────────────── */

.modal-overlay {
  position: fixed;
  inset: 0;
  background: var(--bg-overlay);
  backdrop-filter: blur(4px);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.5rem;
  z-index: 100;
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.22s ease;
}

.modal-overlay.is-open {
  opacity: 1;
  pointer-events: all;
}

/* ── Modal dialog ───────────────────────────────────────────── */

.modal {
  background: var(--bg-modal);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  width: 100%;
  max-width: 420px;
  padding: 2rem;
  transform: translateY(16px) scale(0.97);
  transition: transform 0.24s cubic-bezier(0.34, 1.4, 0.64, 1);
}

.modal-overlay.is-open .modal {
  transform: translateY(0) scale(1);
}

.modal__icon {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: rgba(229, 62, 62, 0.12);
  border: 1px solid rgba(229, 62, 62, 0.3);
  display: flex;
  align-items: center;
  justify-content: center;
  margin-bottom: 1.25rem;
  color: #fc8181;
}

.modal__icon svg {
  width: 22px;
  height: 22px;
}

.modal__title {
  font-size: 1.1rem;
  font-weight: 700;
  color: var(--text-primary);
  margin-bottom: 0.5rem;
}

.modal__body {
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.6;
  margin-bottom: 0.5rem;
}

.modal__filename {
  display: inline-block;
  background: rgba(255,255,255,0.05);
  border: 1px solid var(--border);
  border-radius: 4px;
  padding: 2px 7px;
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 0.8rem;
  color: var(--text-primary);
  margin: 0.5rem 0 1rem;
}

.modal__warning {
  font-size: 0.78rem;
  color: var(--text-muted);
  margin-bottom: 1.5rem;
}

.modal__actions {
  display: flex;
  gap: 0.625rem;
  justify-content: flex-end;
}

.modal__actions .btn {
  flex: unset;
  min-width: 96px;
}

.btn--danger {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #fff;
}

.btn--danger:hover {
  background: var(--accent-red-hover);
  border-color: var(--accent-red-hover);
}
