/* ── Image preview card ─────────────────────────────────────── */

.preview-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  overflow: hidden;
  width: 320px;
  box-shadow: var(--shadow);
}

.preview-card__image-wrap {
  position: relative;
  width: 100%;
  aspect-ratio: 4 / 3;
  background: #12141f;
  overflow: hidden;
}

.preview-card__image-wrap img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.preview-card__badge {
  position: absolute;
  top: 10px;
  right: 10px;
  background: rgba(0, 0, 0, 0.55);
  backdrop-filter: blur(6px);
  color: var(--text-secondary);
  font-size: 0.7rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  padding: 4px 8px;
  border-radius: 4px;
  border: 1px solid rgba(255,255,255,0.08);
}

.preview-card__body {
  padding: 1rem 1.125rem 1.25rem;
}

.preview-card__meta {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 0.875rem;
}

.preview-card__title {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-primary);
  line-height: 1.3;
}

.preview-card__size {
  font-size: 0.75rem;
  color: var(--text-muted);
  white-space: nowrap;
  margin-left: 0.5rem;
  padding-top: 2px;
}

.preview-card__actions {
  display: flex;
  gap: 0.5rem;
}

.btn {
  flex: 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  padding: 0.5rem 0.75rem;
  font-size: 0.8rem;
  font-weight: 600;
  border-radius: var(--radius-sm);
  border: 1px solid transparent;
  cursor: pointer;
  transition: background 0.18s, border-color 0.18s, transform 0.1s;
  letter-spacing: 0.02em;
  line-height: 1;
}

.btn:active {
  transform: scale(0.97);
}

