+  margin-bottom: 0.5rem;
+}
+
+.modal__body {
+  font-size: 0.875rem;
+  color: var(--text-secondary);
+  line-height: 1.6;
+  margin-bottom: 0.5rem;
+}
+
+.modal__filename {
+  display: inline-block;
+  background: rgba(255,255,255,0.05);
